import java.util.HashSet; import java.util.Set; class Solution { public boolean isRectangleCover(int[][] rectangles) { long totalArea = 0; int minX = Integer.MAX_VALUE; int minY = Integer.MAX_VALUE; int maxX = Integer.MIN_VALUE; int maxY = Integer.MIN_VALUE; Set<String> points = new HashSet<>(); for (int[] rect : rectangles) { int x1 = rect[0], y1 = rect[1], x2 = rect[2], y2 = rect[3]; minX = Math.min(minX, x1); minY = Math.min(minY, y1); maxX = Math.max(maxX, x2); maxY = Math.max(maxY, y2); totalArea += (long)(x2 - x1) * (y2 - y1); String[] corners = { x1 + "," + y1, x1 + "," + y2, x2 + "," + y1, x2 + "," + y2 }; for (String corner : corners) { if (!points.add(corner)) { points.remove(corner); } } } if (points.size() != 4 || !points.contains(minX + "," + minY) || !points.contains(minX + "," + maxY) || !points.contains(maxX + "," + minY) || !points.contains(maxX + "," + maxY)) { return false; } return totalArea == (long)(maxX - minX) * (maxY - minY); } }